#!/usr/bin/env python3
"""
Validate DDS source generated by codegen-dspf.

Usage:
  python validate-dspf-source.py --type dspf <file1> [file2 ...]
  python validate-dspf-source.py --type prtf <file1> [file2 ...]
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

DSPSIZ_RE = re.compile(r"\bDSPSIZ\(", re.IGNORECASE)
PRINT_RE = re.compile(r"\bPRINT\b", re.IGNORECASE)
ALIAS_RE = re.compile(r"ALIAS\(([^)]*)\)", re.IGNORECASE)


def is_skippable(line: str) -> bool:
    s = line.strip()
    if not s:
        return True
    if s.startswith("A*"):
        return True
    if s.startswith("*"):
        return True
    return False


def padded80(line: str) -> str:
    return line[:80].ljust(80)


def has_form_type_a_in_col6(line: str) -> bool:
    return len(line) >= 6 and line[5] == "A"


def spec_char_col17(line: str) -> str:
    return padded80(line)[16]


def has_name_col19_28(line: str) -> bool:
    return bool(padded80(line)[18:28].strip())


def has_position_cols39_44(line: str) -> bool:
    pos = padded80(line)[38:44]
    return any(ch.isdigit() for ch in pos)


def get_field_name(line: str) -> str:
    return padded80(line)[18:28].strip()


def infer_usage_code(line: str) -> str:
    # DDS usage markers usually appear near cols 36-38, sometimes fused (e.g. 0O).
    window = padded80(line)[34:40]
    if "H" in window:
        return "H"
    if "P" in window:
        return "P"
    if "B" in window:
        return "B"
    if "I" in window:
        return "I"
    if "O" in window:
        return "O"
    return ""


def is_attr_field_declaration(line: str) -> bool:
    pline = padded80(line)
    field_def = pline[28:37]
    return ("1A" in field_def) and (infer_usage_code(line) == "P")


def has_required_dspatr(lines: list[str], field_line_index: int, field_name: str) -> bool:
    expected = f"DSPATR(&{field_name}A)".upper()
    j = field_line_index + 1
    while j < len(lines):
        nxt = lines[j]
        if is_skippable(nxt):
            j += 1
            continue
        if not has_form_type_a_in_col6(nxt):
            break
        if spec_char_col17(nxt).upper() == "R":
            break
        if get_field_name(nxt):
            break
        if expected in nxt.upper():
            return True
        j += 1
    return False


def validate_dspf_display_attribute_contract(lines: list[str], path: Path) -> list[str]:
    errors: list[str] = []

    current_record = ""
    record_fields: dict[str, str] = {}
    displayable_fields: list[tuple[int, str]] = []

    def flush_record() -> None:
        for line_no, field_name in displayable_fields:
            if len(field_name) > 9:
                errors.append(
                    f"{path}:{line_no}: displayable field '{field_name}' exceeds 9 characters"
                )

            if not has_required_dspatr(lines, line_no - 1, field_name):
                errors.append(
                    f"{path}:{line_no}: displayable field '{field_name}' must include DSPATR(&{field_name}A)"
                )

            attr_name = f"{field_name}A"
            attr_line = record_fields.get(attr_name)
            if attr_line is None:
                errors.append(
                    f"{path}:{line_no}: missing attribute field '{attr_name}' in record '{current_record}'"
                )
                continue
            if not is_attr_field_declaration(attr_line):
                errors.append(
                    f"{path}:{line_no}: attribute field '{attr_name}' must be declared as 1A P"
                )

    for i, line in enumerate(lines, start=1):
        if is_skippable(line) or not has_form_type_a_in_col6(line):
            continue

        if spec_char_col17(line).upper() == "R":
            if current_record:
                flush_record()
            current_record = get_field_name(line)
            record_fields = {}
            displayable_fields = []
            continue

        field_name = get_field_name(line)
        if not field_name:
            continue
        if "(" in field_name or ")" in field_name:
            continue

        record_fields[field_name] = line

        # Displayable = named field with screen position and not hidden/program-only.
        if has_position_cols39_44(line) and infer_usage_code(line) not in {"H", "P"}:
            displayable_fields.append((i, field_name))

    if current_record:
        flush_record()

    return errors


def is_program_addressable_field_spec(line: str) -> bool:
    pline = padded80(line)
    if spec_char_col17(line).upper() == "R":
        return False

    name = pline[18:28].strip()
    if not name:
        return False
    if "(" in name or ")" in name:
        return False

    # Heuristic: field specs carry a length/type/use definition in cols 29-37.
    # Include non-digit type forms (for example zoned/date/time forms).
    field_def = pline[28:37].strip()
    return bool(field_def)


def looks_valid_alias(alias_text: str) -> bool:
    text = alias_text.strip()
    if not text:
        return False
    if len(text) > 25:
        return False
    if " " in text:
        return False
    if not re.fullmatch(r"[A-Za-z0-9_]+", text):
        return False
    return True


def validate_alias_rules(lines: list[str], path: Path) -> list[str]:
    errors: list[str] = []

    def find_alias_for_field(start_index: int) -> str | None:
        current = lines[start_index]
        current_match = ALIAS_RE.search(current)
        if current_match:
            return current_match.group(1).strip()

        j = start_index + 1
        while j < len(lines):
            nxt = lines[j]
            if is_skippable(nxt):
                j += 1
                continue
            if not has_form_type_a_in_col6(nxt):
                break

            pnext = padded80(nxt)
            if spec_char_col17(nxt).upper() == "R":
                break

            # New named spec starts: stop scanning continuations.
            if pnext[18:28].strip():
                break

            alias_match = ALIAS_RE.search(nxt)
            if alias_match:
                return alias_match.group(1).strip()
            j += 1

        return None

    for i, line in enumerate(lines, start=1):
        if is_skippable(line) or not has_form_type_a_in_col6(line):
            continue
        if not is_program_addressable_field_spec(line):
            continue

        alias_text = find_alias_for_field(i - 1)
        if not alias_text:
            errors.append(f"{path}:{i}: program-addressable field is missing ALIAS(...) keyword")
            continue
        if not looks_valid_alias(alias_text):
            errors.append(
                f"{path}:{i}: ALIAS value must use underscores (no spaces) and be 1..25 chars (found '{alias_text}')"
            )

    return errors


def validate_common(lines: list[str], path: Path) -> list[str]:
    errors: list[str] = []
    has_record = False

    for i, line in enumerate(lines, start=1):
        if is_skippable(line):
            continue
        if len(line) > 80:
            errors.append(f"{path}:{i}: DDS source line exceeds 80 columns")
        if not has_form_type_a_in_col6(line):
            errors.append(f"{path}:{i}: DDS line must start with 'A' at column 6 (5 leading spaces)")
        if spec_char_col17(line).upper() == "R":
            has_record = True

    if not has_record:
        errors.append(f"{path}: missing DDS record format line (A ... R ...)")

    return errors


def validate_by_type(member_type: str, text: str, path: Path) -> list[str]:
    errors: list[str] = []
    lines = text.splitlines()

    if member_type == "dspf":
        if not DSPSIZ_RE.search(text):
            errors.append(f"{path}: DSPF is missing DSPSIZ keyword")
        saw_record = False
        for i, line in enumerate(lines, start=1):
            if is_skippable(line) or not has_form_type_a_in_col6(line):
                continue
            if spec_char_col17(line).upper() == "R":
                saw_record = True
                continue
            if not saw_record and (has_name_col19_28(line) or has_position_cols39_44(line)):
                errors.append(
                    f"{path}:{i}: DSPF field/constant-level content appears before first record format"
                )
        errors.extend(validate_dspf_display_attribute_contract(lines, path))
    elif member_type == "prtf":
        if not PRINT_RE.search(text):
            errors.append(f"{path}: PRTF should include PRINT keyword")

    return errors


def validate_file(member_type: str, path: Path) -> list[str]:
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except Exception as ex:
        return [f"{path}: unable to read file ({ex})"]

    lines = text.splitlines()
    if not lines:
        return [f"{path}: file is empty"]

    errors = validate_common(lines, path)
    errors.extend(validate_alias_rules(lines, path))
    errors.extend(validate_by_type(member_type, text, path))
    return errors


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description="Validate DSPF/PRTF source members")
    parser.add_argument("--type", required=True, choices=["dspf", "prtf"], help="DDS member type")
    parser.add_argument("files", nargs="+", help="DDS source files to validate")
    args = parser.parse_args(argv[1:])

    all_errors: list[str] = []
    for raw in args.files:
        path = Path(raw)
        if not path.exists():
            all_errors.append(f"{path}: file does not exist")
            continue
        all_errors.extend(validate_file(args.type, path))

    if all_errors:
        for error in all_errors:
            print(f"ERROR: {error}")
        return 1

    print(f"OK: all {args.type.upper()} files passed DDS checks")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
